-- Pharmacy / chemist global catalog seed from Eastleigh Sept 2026 wholesale pricelist.
-- Pack store_kit_id=pharmacy so onboarding + catalog rank this pack for pharmacy shops.

SET @catalog_id = (
  SELECT id FROM global_catalogs WHERE code = 'default' LIMIT 1
);

INSERT INTO global_categories (
  id, catalog_id, name, slug, position, tenant_category_slug_hint, active
)
SELECT
  '00000000-0000-0000-0000-000000020001', @catalog_id, 'Pharmaceuticals', 'pharmaceuticals', 100, 'pharmaceuticals', TRUE
WHERE @catalog_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM global_categories WHERE catalog_id = @catalog_id AND slug = 'pharmaceuticals'
  );
SET @cat_pharma = (
  SELECT id FROM global_categories WHERE catalog_id = @catalog_id AND slug = 'pharmaceuticals' LIMIT 1
);

INSERT INTO global_categories (
  id, catalog_id, name, slug, position, tenant_category_slug_hint, active
)
SELECT
  '00000000-0000-0000-0000-000000020002', @catalog_id, 'Vital Therapeutics', 'vital-therapeutics', 101, 'vital-therapeutics', TRUE
WHERE @catalog_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM global_categories WHERE catalog_id = @catalog_id AND slug = 'vital-therapeutics'
  );
SET @cat_vital = (
  SELECT id FROM global_categories WHERE catalog_id = @catalog_id AND slug = 'vital-therapeutics' LIMIT 1
);

INSERT INTO global_categories (
  id, catalog_id, name, slug, position, tenant_category_slug_hint, active
)
SELECT
  '00000000-0000-0000-0000-000000020003', @catalog_id, 'Medical Supplies', 'medical-supplies', 102, 'medical-supplies', TRUE
WHERE @catalog_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM global_categories WHERE catalog_id = @catalog_id AND slug = 'medical-supplies'
  );
SET @cat_medsup = (
  SELECT id FROM global_categories WHERE catalog_id = @catalog_id AND slug = 'medical-supplies' LIMIT 1
);

